 b=R/'data/p14r-20261027';out=Path(sys.argv[1]);out.mkdir(parents=True,exist_ok=False);ledger=[json.loads(l) for l in (b/'attempts.jsonl').read_text().splitlines()];starts=[r for r in ledger if r['event']=='START_INTENT'];finish=[r for r in ledger if r['event']=='FINISH'];formal=[r for r in finish if 'd05' in r['id'] or 'd06' in r['id']];raw={};runrows=[]
