 if old.exists():checks={p:sha(R/p)==h for p,h in json.load(open(old)).items()};assert all(checks.values())
 write(out/'historical-preservation.json',{'old_raw_inputs':checks,'old_git_paths':'only maintained current injection/runner/.gitignore/test/patch exports changed; no old data/docs/freeze paths edited','preexisting_dirty':'start-state.json retained; pre-existing AGENTS/receipts not staged','CLI_symlinks':'historical CLI symlink text preserved, resolves shared Lab binary; not a historical binary snapshot. pre-change/runtime-v1/runtime-v2 ordinary copies preserved','A4':'NOT_PROVEN_EXCLUDED'})
