 machine={'schema':'p14r-method-refinement-conclusion-1','baseline':'69ca54ff3029df671de740cf0a4ab4495b03b44a','starts':len(starts),'valid_new_records':len(finish),'quarantined':len(starts)-len(finish),'unused':8-len(starts),'new_flight_stop':'NO_FURTHER_QUESTION_REQUIRES_START; do not use remaining2','records':runrows,'A':{'source_OP_known_input_continuous_replay':'bit exact31fields on all6record prefixes after55s; d01 still invalid full evidence','actual_future_injections':'IMU/fused-target/physical/cache words diagnostic only; autonomous sandbox never receives them','future_model':'source OP with held past fused-target residual and source-shaped sensor integration; actual EKF target dynamics unclosed','clock':{'historical_captures':clock['capture_tested'],'capture_outside_conditional_bracket':clock['capture_missed'],'historical_resumes':clock['resume_tested'],'resume_outside_conditional_bracket':clock['resume_missed'],'future_bounds_not_source_certified':True},'new_d06_initial_OP_lag_us':8000},'B':{'old_reachable_support_points':66,'propagated_old_support':24,'new_source_OP_seed_joint':'d02/d03observed endpoints and4part joint curve, no blanket future coverage','rotor_phase_retained':True,'strict_same_initial_counterfactual':False},'C':{'jobs':cjobs,'full_real_joint_single_event':'NOT_CLOSED','zero_radius':'algorithmic remainder and assumed FP/libm amplification plus declared-real/float-source-center difference; not physical uncertainty or certified true roundoff','nominal_composition_depth':4,'interval_composition_depth_complete_events':0,'future_EKF_SERVO_FP32_safety_certificate':False},'handover':{'real':'C->N RINI4 source operator and subsequent N stop/resume in5valid records; first3entry actions independently replayed','N_to_C_active_classic':'NOT_IMPLEMENTED_NOT_CLAIMED','inactive_classic_integral':'velocity reset on next disabled callback; rate held/unknown, no invented reset'},'score_primary':primary,'storage':{k:v for k,v in storage.items() if k not in ['layout','center']},'A4':'NOT_PROVEN_EXCLUDED','cost_benefit':'NOT_ESTABLISHED','verdict':'source/state/event-map structure and4-event serialized nominal composition work; finite joint nonlinear set propagation and future innovation/clock budgets remain barriers to useful full-event conditional safety. Keep structured map route, do not deploy full-task safety screening or claim reduced simulations yet.'};write(out/'machine-conclusion.json',machine)
 edge={'schema':'moving-correlated-event-map-3','input':{'mode':'N_ACTIVE after observed C->N RINI4 entry','joint_region':'C-final-v5 four seed-origin segments07..10; observed d02/d03 prefixes, no claim entireinterior reachable','initial':'source-inputs-v3/d02/input.json','counterpart':'source-inputs-v3/d03/input.json','event':'stop -> strict native timeout capture -> hold -> resume latest valid delivery -> recovery','clock':'source publisher immediate gap exit, latest slot kept through forbidden reads, source OP producer/cache state; nominal8persistent words + conditional event brackets, not every future legal switching','state':['physicalCOMp/v/q/w/rotorphase','estimatedq/LPframe/bias','OPbuffer+indices/corrections/integrals','gyroDFII','h/previous/mean/count','filter/pending/consumed','reference/captureprofile','publisher/transport/readslot','native/sample/commit','H0/L/D/W/failurelatches'],'model_defects':'future EKFinnovation/SERVO/float32/geodesy budgets not certified'},'output':{'nominal4events':'compose-v2/full.npz','live_successors':['compose-v2/edge-'+str(n)+'-successor.json' for n in range(1,5)],'joint_tube':'C-final-v5/07..10, future is TOP after individual domain loss; never restart h/history/D','64ms_real_joint_quarter':'C-metrics-v1/1/result.json','source_zero_radius_prefix':'C-metrics-v1/0/result.json','full_prefix_margins':'physical tilt/COM L/D and LP/cache separate, rich C metrics; no continuous intersample certificate','safety_status':'CONDITIONAL_PARTIAL_ONLY','storage':'storage-v1/storage.npz with P recurrence and nonlinear remainder obligation','actual_anchors':'d05 F2AB short,d06F4ABmedium, both retained failures'},'composition':{'nominal_depth4':True,'split_vs_uninterrupted_max':max(max(r['split_run_vs_uninterrupted'].values()) for r in compose['rows']),'full_set_depth4':False,'D_monotone_failure_latch_preserved':True,'unknown_after_loss':'TOP with surviving nominal diagnostic, never safe successor'},'scope':'analysis-conditional results/empirical diagnostics/real-record support are separate; prospective P13 scores and old FAIL/STOP unchanged'};write(out/'map-edge.json',edge)
 # Scientific figures: static, exportable, common absolute-time axes.
 import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
 figs=R/'docs/figures/p14r';figs.mkdir(parents=True,exist_ok=True)
 events=json.load(open(b/'event-tables-v2/summary.json'));fig,ax=plt.subplots(1,2,figsize=(10,3.5))
